#include <bits/stdc++.h>
using namespace std;using U=uint64_t;U nb[36];long long bcount=0,brole=0,ccount=0,cconn=0,dcount=0,acount=0;bool found=false;
int pop(U x){return __builtin_popcountll(x);}bool connected(U x){U seen=x&-x,old=0;while(seen!=old){old=seen;U t=seen;while(t){int q=__builtin_ctzll(t);t&=t-1;seen|=nb[q]&x;}}return seen==x;}
vector<int>bits(U x){vector<int>v;while(x){int q=__builtin_ctzll(x);x&=x-1;v.push_back(q);}return v;}
bool acheck(U D,U occupied){vector<U>dom;U all=0;for(int q:bits(D)){U d=nb[q]&~occupied;d&=(U(1)<<36)-1;if(!d)return false;dom.push_back(d);all|=d;}if(pop(all)<7)return false;sort(dom.begin(),dom.end(),[](U a,U b){return pop(a)<pop(b);});function<bool(int,U)>rec=[&](int i,U used){if(i==7){acount++;return connected(used);}U options=dom[i]&~used;while(options){U bit=options&-options;options-=bit;if(rec(i+1,used|bit))return true;}return false;};return rec(0,0);}
int main(){for(int q=0;q<36;q++)for(int p=0;p<36;p++)if(abs(q/6-p/6)+abs(q%6-p%6)==1)nb[q]|=U(1)<<p;
 unordered_set<U>sets;for(int q=0;q<36;q++)sets.insert(U(1)<<q);for(int n=2;n<=7;n++){unordered_set<U>next;for(U x:sets){U boundary=0;for(int q:bits(x))boundary|=nb[q];boundary&=~x;while(boundary){U bit=boundary&-boundary;boundary-=bit;next.insert(x|bit);}}sets=move(next);}bcount=sets.size();
 for(U B:sets){auto bb=bits(B);for(int drop:bb){bool ok=true;for(int q:bb)if(pop(nb[q]&~B)<(q==drop?1:2))ok=false;if(!ok)continue;brole++;vector<pair<int,U>>cd;for(int q:bb)if(q!=drop)cd.push_back({q,nb[q]&~B});sort(cd.begin(),cd.end(),[](auto a,auto b){return pop(a.second)<pop(b.second);});unordered_set<U>cs;
 function<void(int,U)>crec=[&](int i,U C){if(found)return;if(i<6){U options=cd[i].second&~C;while(options){U bit=options&-options;options-=bit;crec(i+1,C|bit);}return;}ccount++;if(!cs.insert(C).second||!connected(C))return;cconn++;vector<U>dd;for(int q:bb){U choices=nb[q]&~(B|C);if(!choices)return;dd.push_back(choices);}sort(dd.begin(),dd.end(),[](U a,U b){return pop(a)<pop(b);});unordered_set<U>ds;
 function<void(int,U)>drec=[&](int j,U D){if(found)return;if(j<7){U choices=dd[j]&~D;while(choices){U bit=choices&-choices;choices-=bit;drec(j+1,D|bit);}return;}if(!ds.insert(D).second)return;dcount++;if(acheck(D,B|C|D)){found=true;cerr<<"COUNTEREXAMPLE B="<<B<<" C="<<C<<" D="<<D<<" drop="<<drop<<"\n";}};drec(0,0);};crec(0,0);if(found)break;}if(found)break;}
 cout<<"{\"status\":\""<<(found?"SAT":"UNSAT")<<"\",\"connected_B_sets\":"<<bcount<<",\"admissible_B_drop_roles\":"<<brole<<",\"C_matchings\":"<<ccount<<",\"connected_C_sets\":"<<cconn<<",\"D_sets\":"<<dcount<<",\"A_matchings_checked\":"<<acount<<"}\n";
}
